create or replace function public.crm_experiment_sample_size_binary(p_baseline numeric default 0.10,p_mde numeric default 0.03,p_alpha numeric default 0.05,p_power numeric default 0.80) returns integer language plpgsql immutable set search_path=pg_catalog,public as $$ declare z_alpha numeric:=1.95996398454005; z_power numeric:=0.841621233572914; p numeric; n numeric; begin if p_baseline<=0 or p_baseline>=1 or p_mde<=0 or p_alpha<=0 or p_alpha>=1 or p_power<=0 or p_power>=1 or p_baseline+p_mde>=1 then raise exception 'invalid_power_parameters'; end if; p=p_baseline; n=((z_alpha*sqrt(2*p*(1-p))+z_power*sqrt(p*(1-p)+(p+p_mde)*(1-p-p_mde)))^2)/(p_mde^2); return ceil(n)::integer; end; $$;